    /**
     * Ein Symbol als Inline-SVG, so wie Font Awesome es beim Tausch von <i>
     * gegen <svg> einsetzt (`svg-inline--fa` mit dem Namen als Klasse); die
     * Groesse regelt das CSS der Kachel bzw. der Vorschau ueber `1em`.
     *
     * Der Name kommt aus der Farbtabelle des Formulars, also aus fremder Hand:
     * nur Kleinbuchstaben, Ziffern und Bindestrich, und nur was in der Liste
     * steht — alles andere wird der Kreis.
     */
    public static function Svg(string $name): string
    {
        $name = str_starts_with($name, 'fa-') ? substr($name, 3) : $name;
        if (preg_match('/^[a-z0-9-]{1,40}$/', $name) !== 1 || !isset(self::PFADE[$name])) {
            $name = self::RUECKFALL;
        }
        $p = self::PFADE[$name];
        /* Der SVG-Namensraum steht ausdruecklich dran: im XHTML eines
           foreignObject waere ein <svg> ohne ihn ein unbekanntes HTML-Element
           und bliebe leer (im Prueflauf gesehen — alle Symbole fehlten). */
        return '<svg xmlns="http://www.w3.org/2000/svg" class="svg-inline--fa fa-' . $name . '" viewBox="' . $p['viewBox']
            . '" fill="currentColor" aria-hidden="true"><path d="' . $p['d'] . '"/></svg>';
    }
